// Fictional text PDF in the vendor's published statement layout, not a vendor file.
export const statementLines=[
 'Laytime Statement Layline',
 'Vessel MV Example Imported Port Napier IMO 1234567 Events 3',
 'Charter terms',
 'Demurrage rate $12,000.00 / day Despatch rate $6,000.00 / day',
 'Allowed laytime 48.00 h Turn-time 0.00 h',
 'Weekend rule SHINC Laytime type NON REVERSIBLE',
 'Statement of facts',
 'ID Timestamp Event Counts Factor',
 'E1 2026-01-01 00:00 UTC NOR ACCEPTED Yes 100%',
 'E2 2026-01-01 02:00 UTC CARGO COMMENCED Yes 100%',
 'E3 2026-01-04 00:00 UTC CARGO COMPLETED Yes 100%',
 'Computation',
 'Generated by Layline'
];
export function makePdf(lines=statementLines){
 const escape=s=>s.replaceAll('\\','\\\\').replaceAll('(','\\(').replaceAll(')','\\)');
 const stream='BT /F1 10 Tf 40 780 Td 20 TL '+lines.map((s,i)=>(i?'T* ':'')+'('+escape(s)+') Tj').join('\n')+' ET';
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`];
 let pdf='%PDF-1.4\n';const offsets=[0];for(let i=0;i<objects.length;i++){offsets.push(Buffer.byteLength(pdf));pdf+=`${i+1} 0 obj\n${objects[i]}\nendobj\n`;}
 const xref=Buffer.byteLength(pdf);pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(n=>`${String(n).padStart(10,'0')} 00000 n \n`).join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;return Buffer.from(pdf);
}
